import{c as e,d as t,h as n,k as r,m as i,t as a,vt as o}from"./chunks/plugin-vue_export-helper.sM-KdTqA.js";const s=JSON.parse(`{"title":"自定义组件开发与组件商城","description":"","frontmatter":{},"headers":[],"relativePath":"guide/custom-components.md","filePath":"guide/custom-components.md"}`);var c={name:`guide/custom-components.md`};function l(a,s,c,l,u,d){return r(),t(`div`,null,[s[18]||=i(`<h1 id="自定义组件开发与组件商城" tabindex="-1">自定义组件开发与组件商城 <a class="header-anchor" href="#自定义组件开发与组件商城" aria-label="Permalink to “自定义组件开发与组件商城”">​</a></h1><p>虽然 QC Flutter Flow 内置了 <strong>90+ 常用系统组件</strong>，但在实际企业业务中，你往往需要封装团队专属的业务控件（例如：带倒计时的抢购卡片、定制物流轨迹图、特殊行业表单控件）。</p><p>平台内置了独立的 <strong>「组件开发工作台」</strong> 与 <strong>「组件商城」</strong>，让你无需修改主平台源码，就能可视化定义、测试并共享自定义组件。</p><hr><h2 id="一、进入组件开发工作台" tabindex="-1">一、进入组件开发工作台 <a class="header-anchor" href="#一、进入组件开发工作台" aria-label="Permalink to “一、进入组件开发工作台”">​</a></h2><ol><li>在主控管理台左侧点击 <strong>「组件开发」</strong>。</li><li>点击右上角 <strong>「+ 新建组件工程」</strong>，填写： <ul><li><strong>组件中文名称</strong>（如 <code>优惠券卡片</code>）</li><li><strong>包名标识 (Package Name)</strong>（如 <code>com.qc.coupon_card</code>）</li><li><strong>所属分类</strong>（如 <code>基础组件</code>、<code>表单组件</code>、<code>数据组件</code>）</li><li><strong>组件图标 Logo</strong>（内置图标选择器）</li></ul></li></ol><p>双击新建的组件卡片，即可进入包含 <strong>6 大配置标签页</strong> 的组件编辑器。</p><hr><h2 id="二、五步定义你的专属组件" tabindex="-1">二、五步定义你的专属组件 <a class="header-anchor" href="#二、五步定义你的专属组件" aria-label="Permalink to “二、五步定义你的专属组件”">​</a></h2><h3 id="_1-基础配置-basic-config" tabindex="-1">1. 基础配置（Basic Config） <a class="header-anchor" href="#_1-基础配置-basic-config" aria-label="Permalink to “1. 基础配置（Basic Config）”">​</a></h3><p>设置组件的显示名称、版本号（如 <code>1.0.0</code>）、组件分类、一句话功能描述以及组件图标。</p><h3 id="_2-属性配置-properties-——-定义右侧面板能改什么" tabindex="-1">2. 属性配置（Properties）—— 定义右侧面板能改什么 <a class="header-anchor" href="#_2-属性配置-properties-——-定义右侧面板能改什么" aria-label="Permalink to “2. 属性配置（Properties）—— 定义右侧面板能改什么”">​</a></h3><p>在这里添加的属性，会在用户把该组件拖入主画布后，自动呈现在主画布右侧的「属性检查器」中：</p><ul><li><strong>属性中文名</strong>（如 <code>优惠金额</code>、<code>按钮文字</code>、<code>是否已领取</code>）</li><li><strong>属性英文编码 (<code>attrCode</code>)</strong>（如 <code>amount</code>、<code>btnText</code>、<code>isClaimed</code>）</li><li><strong>数据类型</strong>：支持 <code>文本 (String)</code>、<code>整数 (Int)</code>、<code>小数 (Double)</code>、<code>布尔开关 (Bool)</code>、<code>颜色 (Color)</code>、<code>列表 (List)</code>、<code>字典 (Map)</code>。</li><li><strong>默认值</strong>与<strong>中文口语别名</strong>（设置别名后，用户在代码或 AI 对话中用口语也能操控该属性）。</li></ul><h3 id="_3-方法配置-methods-——-定义代码里能调用什么动作" tabindex="-1">3. 方法配置（Methods）—— 定义代码里能调用什么动作 <a class="header-anchor" href="#_3-方法配置-methods-——-定义代码里能调用什么动作" aria-label="Permalink to “3. 方法配置（Methods）—— 定义代码里能调用什么动作”">​</a></h3><p>定义该组件对外暴露的控制方法（例如：<code>设置优惠金额(val)</code>、<code>重置状态()</code>），方便用户在页面 DSL 代码中直接通过 <code>组件ID.方法名()</code> 调用。</p><h3 id="_4-事件配置-events-——-定义组件能触发什么回调" tabindex="-1">4. 事件配置（Events）—— 定义组件能触发什么回调 <a class="header-anchor" href="#_4-事件配置-events-——-定义组件能触发什么回调" aria-label="Permalink to “4. 事件配置（Events）—— 定义组件能触发什么回调”">​</a></h3><p>定义用户交互时触发的事件（例如：<code>点击领取事件 (onClaim)</code>，并可配置回调携带的参数如 <code>券ID</code>）。</p><h3 id="_5-可视化预览契约画布-ui-contract-——-让组件在画布上所见即所得" tabindex="-1">5. 可视化预览契约画布（UI Contract）—— 让组件在画布上所见即所得 <a class="header-anchor" href="#_5-可视化预览契约画布-ui-contract-——-让组件在画布上所见即所得" aria-label="Permalink to “5. 可视化预览契约画布（UI Contract）—— 让组件在画布上所见即所得”">​</a></h3>`,19),e(`p`,null,[s[0]||=n(`为了让第三方组件拖入主画布后拥有高保真的实时预览效果，你可以在 `,-1),s[1]||=e(`strong`,null,`「预览契约画布」`,-1),s[2]||=n(` 中用基础原语（容器、横向/纵向排布、文本、图片、按钮）搭出它的预览外观，并使用 `,-1),e(`strong`,null,[e(`code`,null,o(a.属性编码),1)]),s[3]||=n(` 绑定前面定义的属性：`,-1)]),e(`ul`,null,[e(`li`,null,[s[4]||=e(`strong`,null,`文字插值绑定`,-1),s[5]||=n(`：在契约文本中输入 `,-1),e(`code`,null,`￥`+o(a.amount),1),s[6]||=n(` 或 `,-1),e(`code`,null,o(a.btnText),1),s[7]||=n(`，或者直接点击属性右侧的 `,-1),s[8]||=e(`strong`,null,`🔗 绑定按钮`,-1),s[9]||=n(` 从下拉菜单中选择匹配类型的属性。`,-1)]),e(`li`,null,[s[10]||=e(`strong`,null,`显隐控制绑定`,-1),s[11]||=n(`：在节点的 `,-1),s[12]||=e(`code`,null,`visible`,-1),s[13]||=n(` 属性绑定 `,-1),e(`code`,null,o(a.isClaimed),1),s[14]||=n(`，当用户在主画布切换开关时，预览画布上的对应区域会实时显示或隐藏。`,-1)]),e(`li`,null,[s[15]||=e(`strong`,null,`重命名自动同步`,-1),s[16]||=n(`：如果你在「属性配置」里修改了某个属性的英文编码，契约画布中绑定的 `,-1),e(`code`,null,o(a.旧编码),1),s[17]||=n(` 会自动同步更新，若有已删除的失效属性也会以红色徽章醒目提醒。`,-1)])]),s[19]||=i(`<hr><h2 id="三、ai-辅助生成组件代码与沙盒测试" tabindex="-1">三、AI 辅助生成组件代码与沙盒测试 <a class="header-anchor" href="#三、ai-辅助生成组件代码与沙盒测试" aria-label="Permalink to “三、AI 辅助生成组件代码与沙盒测试”">​</a></h2><p>在 <strong>「代码编辑 (Code Editor)」</strong> 标签页中：</p><ol><li><strong>AI 一键生成组件实现</strong>：点击工具栏的 <strong>「🤖 AI 生成组件」</strong>，输入你想要的交互效果与样式描述，AI 会自动根据你配置好的属性、方法与事件签名，生成完整的组件实现代码。</li><li><strong>其他依赖与原生权限配置（Other Config）</strong>：如果该组件需要引用第三方 Pub 依赖包，或者需要调用手机相机、定位、蓝牙等 Android / iOS 原生权限，可在「其他配置」中一键声明。</li><li><strong>沙盒独立运行与备份恢复</strong>： <ul><li>点击顶部 <strong>「沙盒运行测试」</strong>，可在独立沙盒窗口中真实运行并调试该组件。</li><li>内置 <strong>「历史备份管理」</strong>，每次重要修改可随时创建快照并一键回滚。</li></ul></li></ol><hr><h2 id="四、发布到主画布或上传组件商城" tabindex="-1">四、发布到主画布或上传组件商城 <a class="header-anchor" href="#四、发布到主画布或上传组件商城" aria-label="Permalink to “四、发布到主画布或上传组件商城”">​</a></h2><p>组件测试通过后：</p><ol><li><strong>一键挂载到主画布物料库</strong>：点击右上角 <strong>「发布到本地物料库」</strong>。回到你的应用项目画布，在左侧「物料库」即可直接看到刚刚做好的组件，拖入画布即可立即使用！</li><li><strong>共享到组件商城</strong>：点击 <strong>「发布到商城」</strong>，团队其他成员即可在主控台的 <strong>「组件商城」</strong> 中浏览、预览并一键安装你开发的组件。</li></ol>`,8)])}var u=a(c,[[`render`,l]]);export{s as __pageData,u as default};